from typing import List

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        n = len(coins)

        def best_starting_at_left() -> int:
            ans = 0
            total = 0
            j = 0

            for i in range(n):
                start = coins[i][0]
                end = start + k - 1

                while j < n and coins[j][1] <= end:
                    total += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                    j += 1

                cur = total
                if j < n and coins[j][0] <= end:
                    cur += (end - coins[j][0] + 1) * coins[j][2]

                ans = max(ans, cur)

                if j > i:
                    total -= (coins[i][1] - coins[i][0] + 1) * coins[i][2]
                else:
                    j = i + 1

            return ans

        def best_ending_at_right() -> int:
            ans = 0
            total = 0
            j = 0

            for i in range(n):
                end = coins[i][1]
                start = end - k + 1

                total += (coins[i][1] - coins[i][0] + 1) * coins[i][2]

                while j <= i and coins[j][1] < start:
                    total -= (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                    j += 1

                cur = total
                if j <= i and coins[j][0] < start:
                    cur -= (start - coins[j][0]) * coins[j][2]

                ans = max(ans, cur)

            return ans

        return max(best_starting_at_left(), best_ending_at_right())
